INSERT OR REPLACE INTO quests (id, zone, template, difficulty, canon, json) VALUES ('Q012','Z3_TOWER_OF_TIME','RUNE_SCAN',5,1,'{"id":"Q012","zone":"Z3_TOWER_OF_TIME","template":"RUNE_SCAN","difficulty":5,"canon":true,"story":{"title":{"en":"The Lost Diary","uz":"Yo‘qolgan Kundalik","ru":"Потерянный Дневник"},"summary":{"en":"Read a diary page to find what happened yesterday.","uz":"Kecha nima bo‘lganini bilish uchun kundalikni o‘qing.","ru":"Прочти дневник, чтобы узнать, что было вчера."},"npc":"Chronist Sol","cutscene_key":"cs_diary","lore_unlock":"lore_past_01"},"tasks":[{"id":"T1","type":"READ_MCQ","prompt":{"en":"Diary: ''Yesterday I walked to the tower.'' What did I do?","uz":"Kundalik: ''Yesterday I walked to the tower.'' Men nima qildim?","ru":"Дневник: ''Yesterday I walked to the tower.'' Что я сделал?"},"choices":[{"id":"A","text":{"en":"walked to the tower","uz":"minoraga piyoda bordim","ru":"пошёл к башне"}},{"id":"B","text":{"en":"walk to the tower","uz":"minoraga piyoda boraman","ru":"иду к башне"}},{"id":"C","text":{"en":"am walking to the tower","uz":"minoraga ketayapman","ru":"иду сейчас к башне"}}],"expected":{"choiceId":"A"},"scoring":{"maxPoints":5,"partial":false,"tags":["PAST_SIMPLE_REGULAR","READ_SCAN_FOR_DETAILS"]},"supportsLocales":["en","uz","ru"]}],"battle":{"enemy":{"name":{"en":"Diary Shade","uz":"Kundalik Soyasi","ru":"Тень Дневника"},"archetype":"SHADE","introLine":{"en":"Yesterday leaves traces.","uz":"Kecha iz qoldiradi.","ru":"Вчера оставляет следы."}},"playerHP":8,"enemyHP":7,"timeLimitSec":120,"attackPerCorrect":3,"damagePerWrong":2},"rewards":{"xp":135,"shards":105,"items":["ITEM_DIARY_PAGE"],"badgeKey":"badge_reading_02"},"antiLeak":{"forbiddenTerms":["IELTS","band","Cambridge","British Council","IDP","test","exam","task 2","listening section"],"uiNeverShow":["CEFR","A1","A2","B1","B2","C1","C2"]}}');
INSERT OR REPLACE INTO quests (id, zone, template, difficulty, canon, json) VALUES ('Q013','Z3_TOWER_OF_TIME','SPELL_FORGE',6,1,'{"id":"Q013","zone":"Z3_TOWER_OF_TIME","template":"SPELL_FORGE","difficulty":6,"canon":true,"story":{"title":{"en":"Irregular Sparks","uz":"Noqonuniy Uchqunlar","ru":"Искры Неправильных"},"summary":{"en":"Fix the core irregular verbs to stop the sparks.","uz":"Uchqunlarni to‘xtatish uchun asosiy irregular fe’llarni tuzating.","ru":"Исправь основные неправильные глаголы, чтобы остановить искры."},"npc":"Chronist Sol","cutscene_key":"cs_irregular","lore_unlock":"lore_irregular_01"},"tasks":[{"id":"T1","type":"MCQ","prompt":{"en":"Choose past: go → ___","uz":"O‘tgan zamonini tanlang: go → ___","ru":"Выбери прошедшее: go → ___"},"choices":[{"id":"A","text":{"en":"goed","uz":"goed","ru":"goed"}},{"id":"B","text":{"en":"went","uz":"went","ru":"went"}},{"id":"C","text":{"en":"gone","uz":"gone","ru":"gone"}}],"expected":{"choiceId":"B"},"scoring":{"maxPoints":4,"partial":false,"tags":["IRREGULAR_VERBS_CORE"]},"supportsLocales":["en","uz","ru"]},{"id":"T2","type":"MCQ","prompt":{"en":"Choose past: have → ___","uz":"O‘tgan zamonini tanlang: have → ___","ru":"Выбери прошедшее: have → ___"},"choices":[{"id":"A","text":{"en":"haved","uz":"haved","ru":"haved"}},{"id":"B","text":{"en":"had","uz":"had","ru":"had"}},{"id":"C","text":{"en":"have","uz":"have","ru":"have"}}],"expected":{"choiceId":"B"},"scoring":{"maxPoints":4,"partial":false,"tags":["IRREGULAR_VERBS_CORE"]},"supportsLocales":["en","uz","ru"]}],"battle":{"enemy":{"name":{"en":"Spark Wraith","uz":"Uchqun Arvohi","ru":"Призрак Искр"},"archetype":"WRAITH","introLine":{"en":"Wrong past forms burn.","uz":"Noto‘g‘ri o‘tgan zamon kuydiradi.","ru":"Неверные формы обжигают."}},"playerHP":8,"enemyHP":8,"timeLimitSec":120,"attackPerCorrect":3,"damagePerWrong":3},"rewards":{"xp":160,"shards":130,"items":["ITEM_IRREGULAR_TALISMAN"],"badgeKey":"badge_irregular_01"},"antiLeak":{"forbiddenTerms":["IELTS","band","Cambridge","British Council","IDP","test","exam","task 2","listening section"],"uiNeverShow":["CEFR","A1","A2","B1","B2","C1","C2"]}}');
INSERT OR REPLACE INTO quests (id, zone, template, difficulty, canon, json) VALUES ('Q014','Z3_TOWER_OF_TIME','TRADE_PACT',6,1,'{"id":"Q014","zone":"Z3_TOWER_OF_TIME","template":"TRADE_PACT","difficulty":6,"canon":true,"story":{"title":{"en":"Report to the Chronist","uz":"Xronistga Hisobot","ru":"Отчёт Хрониста"},"summary":{"en":"Write 2 sentences: what you did and what you are doing now.","uz":"2 gap yozing: kecha nima qildingiz va hozir nima qilyapsiz.","ru":"Напиши 2 предложения: что сделал и что делаешь сейчас."},"npc":"Chronist Sol","cutscene_key":"cs_report","lore_unlock":"lore_writing_02"},"tasks":[{"id":"T1","type":"SHORT_TEXT","prompt":{"en":"Write 2 sentences. Sentence 1: Yesterday… (past). Sentence 2: Now… (present continuous).","uz":"2 gap yozing. 1-gap: Yesterday… (past). 2-gap: Now… (present continuous).","ru":"Напиши 2 предложения. 1: Yesterday… (past). 2: Now… (present continuous)."},"expected":{"rubric":{"mustIncludeAny":["yesterday"],"mustIncludeAny2":["now"],"maxWords":28}},"scoring":{"maxPoints":10,"partial":true,"tags":["PAST_SIMPLE_REGULAR","PRESENT_CONTINUOUS_NOW","BASIC_CONNECTORS_AND_BUT_BECAUSE"]},"supportsLocales":["en","uz","ru"]}],"battle":{"enemy":{"name":{"en":"Chronicle Shade","uz":"Yilnoma Soyasi","ru":"Тень Хроник"},"archetype":"SHADE","introLine":{"en":"Two times. Two sentences.","uz":"Ikki vaqt. Ikki gap.","ru":"Два времени. Два предложения."}},"playerHP":9,"enemyHP":8,"timeLimitSec":200,"attackPerCorrect":3,"damagePerWrong":3},"rewards":{"xp":175,"shards":145,"items":["ITEM_CHRONIST_SEAL"],"badgeKey":"badge_writing_03"},"antiLeak":{"forbiddenTerms":["IELTS","band","Cambridge","British Council","IDP","test","exam","task 2","listening section"],"uiNeverShow":["CEFR","A1","A2","B1","B2","C1","C2"]}}');
INSERT OR REPLACE INTO quests (id, zone, template, difficulty, canon, json) VALUES ('Q015','Z3_TOWER_OF_TIME','GATE_SPEAK',6,1,'{"id":"Q015","zone":"Z3_TOWER_OF_TIME","template":"GATE_SPEAK","difficulty":6,"canon":true,"story":{"title":{"en":"The Tower Gate","uz":"Minora Darvozasi","ru":"Врата Башни"},"summary":{"en":"Speak a longer line to open the final MVP gate.","uz":"MVP yakuniy darvozasini ochish uchun uzunroq gap ayting.","ru":"Скажи длинную фразу, чтобы открыть финальные ворота MVP."},"npc":"Gate Sentinel Lumen","cutscene_key":"cs_mvp_gate","lore_unlock":"lore_tower_01"},"tasks":[{"id":"T1","type":"SPEAK","prompt":{"en":"Say: ''Yesterday I walked here, and now I am studying.''","uz":"Ayting: ''Yesterday I walked here, and now I am studying.''","ru":"Скажи: ''Yesterday I walked here, and now I am studying.''"},"expected":{"targetPhraseEn":"Yesterday I walked here, and now I am studying.","keywords":["yesterday","walked","now","am","studying"]},"scoring":{"maxPoints":10,"partial":true,"tags":["PRONUN_CORE_VOWELS","PAST_SIMPLE_REGULAR","PRESENT_CONTINUOUS_NOW"]},"supportsLocales":["en","uz","ru"]}],"battle":{"enemy":{"name":{"en":"Glyph Sentinel","uz":"Glif Qo‘riqchi","ru":"Страж Глифов"},"archetype":"SENTINEL","introLine":{"en":"Speak the timeline.","uz":"Vaqt chizig‘ini ayting.","ru":"Произнеси линию времени."}},"playerHP":9,"enemyHP":9,"timeLimitSec":75,"attackPerCorrect":4,"damagePerWrong":4},"rewards":{"xp":200,"shards":180,"items":["ITEM_TOWER_PASS"],"badgeKey":"badge_mvp_complete"},"antiLeak":{"forbiddenTerms":["IELTS","band","Cambridge","British Council","IDP","test","exam","task 2","listening section"],"uiNeverShow":["CEFR","A1","A2","B1","B2","C1","C2"]}}');
